$(document).ready(function(){$("#menuToggle").on("click",function(){$("#mobileMenu").removeClass("-translate-x-full").addClass("translate-x-0")}),$("#menuClose").on("click",function(){$("#mobileMenu").removeClass("translate-x-0").addClass("-translate-x-full")});const n=$(".faq-item");n.length>0&&n.each(function(){const n=$(this).find(".faq-question");n.on("click",()=>{$(this).toggleClass("active")})})});